import{_ as e,o as i,c as n,at as l}from"./chunks/framework.CY22Hent.js";const t="/assets/crawler_2026-03-30_150216_613.DwNzHfQL.png",s="/assets/crawler_2026-03-30_155930_233.CllGcKRg.png",p="/assets/crawler_2026-03-30_155138_229.0gkLnWeF.png",r="/assets/crawler_2026-03-30_151856_126.Ch9_UqiO.png",o="/assets/crawler_2026-03-30_161331_784.Bz2FHowI.png",d="/assets/crawler_2026-03-30_161711_466.CTdZ6es0.png",c="/assets/crawler_2026-03-30_152528_173.CetyMLgQ.png",h="/assets/crawler_2026-03-30_153505_729.D4Mst_2j.png",g="/assets/crawler_2026-03-30_155639_926.e4f1S8MV.png",S=JSON.parse('{"title":"手机USB调试微信内置网页","description":"","frontmatter":{"title":"手机USB调试微信内置网页","date":"2026-03-28T00:00:00.000Z","lastUpdated":"2026-03-28T00:00:00.000Z","categories":["爬虫"],"tags":["爬虫"]},"headers":[],"relativePath":"blogs/爬虫/手机USB调试微信内置网页.md","filePath":"blogs/爬虫/手机USB调试微信内置网页.md"}'),_={name:"blogs/爬虫/手机USB调试微信内置网页.md"};function k(b,a,B,u,m,F){return i(),n("div",null,[...a[0]||(a[0]=[l('<p>[toc]</p><h1 id="手机usb调试微信内置网页" tabindex="-1">手机USB调试微信内置网页 <a class="header-anchor" href="#手机usb调试微信内置网页" aria-label="Permalink to &quot;手机USB调试微信内置网页&quot;">​</a></h1><p>在爬虫开发中，如果我们想要爬取微信公众号或微信网页的数据的时候。这些网页数据只能在微信内置浏览器中打开。无法在普通的浏览器中打开。因此我们需要调试微信内置浏览器中的网页。</p><p>如图所示,普通的浏览器无法访问微信网页。 <img src="'+t+`" alt="crawler_2026-03-30_150216_613.png" loading="lazy"></p><p>本文将详细介绍如何通过USB连接手机，调试微信内置网页。</p><h2 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h2><ul><li>Android手机 / iOS手机</li><li>USB数据线(可以传输数据的USB数据线)</li><li>电脑（Windows或Mac）</li><li>Chrome浏览器 / Edge浏览器（最新版本）</li></ul><h2 id="开启手机开发者选项" tabindex="-1">开启手机开发者选项 <a class="header-anchor" href="#开启手机开发者选项" aria-label="Permalink to &quot;开启手机开发者选项&quot;">​</a></h2><p>注意：不同的手机开启开发者选项的方法不同。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 开启步骤：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 打开手机「设置」</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">2.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 进入「关于手机」</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">3.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 连续点击「版本号」7次，激活开发者模式</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">4.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 返回「设置」，进入「系统和更新」→「开发人员选项」</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">5.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 开启「USB调试」开关</span></span></code></pre></div><h2 id="电脑连接手机进行usb调试" tabindex="-1">电脑连接手机进行USB调试 <a class="header-anchor" href="#电脑连接手机进行usb调试" aria-label="Permalink to &quot;电脑连接手机进行USB调试&quot;">​</a></h2><p>① 通过USB数据线连接手机到电脑，选择「传输文件」模式</p><p>② 手机上会弹出一个提示框，询问是否允许USB调试。如果没有这个提示框，说明手机没有开启USB调试功能。或者说明电脑没有开启 ADB 服务。</p><p>如图所示。 <img src="`+s+'" alt="crawler_2026-03-30_155930_233.png" loading="lazy"></p><p>③ 打开手机微信，在手机微信内部访问这个链接。<code> http://debugxweb.qq.com/?inspector=true</code>。当打开这个链接，弹出“执行成功”，即可。</p><p>如图所示 <img src="'+p+'" alt="crawler_2026-03-30_155138_229.png" loading="lazy"></p><p>④ 然后在手机微信内部打开想要抓包调试的网页</p><p>⑤ 电脑上打开chrome浏览器或edge浏览器。</p><ul><li>chrome浏览器访问 chrome://inspect/#devices</li><li>edge浏览器访问 edge://inspect/#devices</li></ul><p>⑥ 会进入到浏览器的「Devices」开发工具界面中。</p><p>如图所示 <img src="'+r+'" alt="crawler_2026-03-30_151856_126.png" loading="lazy"></p><p>⑦ 稍等片刻，浏览器会自动检测到手机微信内部打开的网页。</p><p>如果浏览器没有自动检测到手机微信内部打开的网页，说明手机没有开启USB调试功能。或者说明电脑没有开启 ADB 服务。</p><p>如图红框所示，就是手机设备信息。 <img src="'+o+'" alt="crawler_2026-03-30_161331_784.png" loading="lazy"></p><p>⑧ 找到手机微信内部打开的网页，点击「Inspect fallback」按钮。然后电脑上就会弹出该网页的调试界面。</p><p>如图左边是网页界面，右边是调试界面。 <img src="'+d+'" alt="crawler_2026-03-30_161711_466.png" loading="lazy"></p><p>⑨ 后面就可以通过 network 网络选项，来调试该网页的网络请求。</p><h2 id="手机usb调试中的-pending-authentication-please-accept-debugging-session-on-the-device-问题" tabindex="-1">手机USB调试中的 <code>Pending authentication: please accept debugging session on the device</code> 问题 <a class="header-anchor" href="#手机usb调试中的-pending-authentication-please-accept-debugging-session-on-the-device-问题" aria-label="Permalink to &quot;手机USB调试中的 `Pending authentication: please accept debugging session on the device` 问题&quot;">​</a></h2><p>有时候，我们可能会遇到如下问题：<code>Pending authentication: please accept debugging session on the device</code> 。中文翻译为：待认证：请在设备上接受调试会话</p><p><img src="'+c+`" alt="crawler_2026-03-30_152528_173.png" loading="lazy"></p><p>出现这个问题的原因是因为电脑没有开启 ADB 服务。即电脑无法通过USB调试手机。</p><h3 id="什么是-adb-服务" tabindex="-1">什么是 ADB 服务？ <a class="header-anchor" href="#什么是-adb-服务" aria-label="Permalink to &quot;什么是 ADB 服务？&quot;">​</a></h3><p>ADB (Android Debug Bridge) 是Android开发工具包（SDK）中的一个命令行工具，用于在电脑和Android设备之间建立通信桥梁。它允许开发者通过 USB 连接 Android 和 电脑，进行调试和开发。</p><p>当手机与电脑连接出现问题时，重启ADB服务可以刷新连接状态，解决授权或通信异常。</p><h3 id="如何重启adb服务" tabindex="-1">如何重启ADB服务？ <a class="header-anchor" href="#如何重启adb服务" aria-label="Permalink to &quot;如何重启ADB服务？&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在电脑上打开CMD命令提示符或PowerShell</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 执行下面命令，重启ADB服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill-server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start-server</span></span></code></pre></div><p>如果电脑无法识别adb命令，说明电脑没有安装ADB工具。需要先安装ADB工具，才能使用adb命令。</p><h3 id="如何安装adb服务" tabindex="-1">如何安装ADB服务？ <a class="header-anchor" href="#如何安装adb服务" aria-label="Permalink to &quot;如何安装ADB服务？&quot;">​</a></h3><ol><li>访问 Android开发者官网 <code>https://developer.android.google.cn/tools/releases/platform-tools?hl=zh-cn</code>。</li></ol><p>如图所示 <img src="`+h+'" alt="crawler_2026-03-30_153505_729.png" loading="lazy"></p><ol start="2"><li>下载最新的Android SDK Platform-Tools工具包。并将安装包解压到电脑的某个目录中。</li><li>将该目录添加到系统环境变量（确保目录中的 adb.exe 可直接运行）</li><li>重新打开命令提示符，执行 <code>adb version</code> 命令验证ADB服务是否启动成功。</li></ol><p>也可以暂时不配置环境变量，在安装目录下执行adb devices命令，立即启动ADB服务。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devices</span></span></code></pre></div><p>如图所示。 <img src="'+g+'" alt="crawler_2026-03-30_155639_926.png" loading="lazy"></p><p>当ADB服务启动成功后，手机上会弹出一个提示框，询问是否允许USB调试。点击「允许」即可开启USB调试。 <img src="'+s+'" alt="crawler_2026-03-30_155930_233.png" loading="lazy"></p>',45)])])}const A=e(_,[["render",k]]);export{S as __pageData,A as default};
